//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this failure may be retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn only_transient_errors_are_retryable() {
        assert!(RetryError::Transient("temporary".into()).is_transient());
        assert!(!RetryError::Permanent("invalid".into()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry numbered from zero.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        let multiplier = 1u64.checked_shl(retry_number).unwrap_or(u64::MAX);
        self.base_delay_ms
            .checked_mul(multiplier)
            .unwrap_or(u64::MAX)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_is_exponential_and_saturates() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 25,
        };

        assert_eq!(config.delay_for_retry(0), 10);
        assert_eq!(config.delay_for_retry(1), 20);
        assert_eq!(config.delay_for_retry(2), 25);
        assert_eq!(config.delay_for_retry(32), 25);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);

    for attempt in 1..=max_attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt == max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(config.delay_for_retry(attempt - 1));
            }
        }
    }

    unreachable!("the retry loop always returns from its final attempt")
}

# jobrunner

Small job runner with a pluggable retry policy.

## Retry policy

`run_job` accepts a `RetryConfig` and retries only `RetryError::Transient`
failures. `RetryError::Permanent` failures are returned immediately.
`max_attempts` is the total number of calls, including the initial call.

Delays use exponential backoff: the first retry waits `base_delay_ms`, and
each later retry doubles that delay until it reaches `max_delay_ms`. The
`sleeper` argument is injectable, so callers can provide a real sleeper while
tests can record delays without waiting.

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig {
    max_attempts: 4,
    base_delay_ms: 100,
    max_delay_ms: 1_000,
};
let mut sleeper = FakeSleeper::default();
let mut calls = 0;
let result = run_job(&config, &mut sleeper, || {
    calls += 1;
    if calls < 3 {
        Err(RetryError::Transient("temporary outage".into()))
    } else {
        Ok(())
    }
});
assert!(result.is_ok());
assert_eq!(sleeper.sleeps, vec![100, 200]);
```

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms: 10,
        max_delay_ms: 25,
    }
}

#[test]
fn retries_transient_failures_then_succeeds() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(4), &mut sleeper, || {
        calls += 1;
        if calls < 3 {
            Err(RetryError::Transient("temporary".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn permanent_failure_returns_without_retrying() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(4), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_includes_initial_call_and_delays_saturate() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(5), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("still down".into()))
    });

    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    assert_eq!(result, Err(RetryError::Transient("still down".into())));
}
